// === ACROBATICS CHECK for Fantastic Depths - Thanks FR4NC35C0 for posting your version to our Discord server. This is a slight modification to your macro. ===

const actor = canvas.tokens.controlled[0]?.actor ?? game.user.character;
if (!actor) {
  return ui.notifications.warn("❌ Please select a token on the scene!");
}

// Retrieve Dex and Level - optimized for Fantastic Depths
const dex = Number(
  actor.system.abilities?.dex?.value ??
  actor.system.attributes?.dex?.value ??
  actor.system.abilities?.dex ??
  10
);

let lvl = Number(
  actor.system.class?.level ?? 
  actor.system.details?.level?.value ??
  actor.system.level?.value ??
  actor.system.details?.level ??
  actor.system.details?.lvl ??
  actor.system.class?.levels ??
  actor.system.details?.classLevel ??
  actor.system.details?.experience?.level ?? 
  1
);

const target = 3 * dex + 2 * lvl;

// Create and evaluate the Roll (v12+ syntax)
const roll = new Roll("1d100");
await roll.evaluate();

const rollTotal = roll.total;
const isSuccess = rollTotal < target;

// Badge styling
const statusText = isSuccess ? "Success" : "Failure";
const badgeBg = isSuccess ? "#2e7d32" : "#c62828"; // Muted dark green / red

// Clean, compact Chat HTML
const messageContent = `
<div style="font-family: var(--font-primary); font-size: 13px;">
  <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;">
    <strong>Acrobatics Check</strong>
    <span style="background: ${badgeBg}; color: #fff; padding: 2px 8px; border-radius: 4px; font-weight: bold; font-size: 11px;">
      ${statusText}
    </span>
  </div>

  <table style="width: 100%; border-collapse: collapse; text-align: left; font-size: 12px; margin: 0;">
    <tr style="border-bottom: 1px solid rgba(0,0,0,0.1);">
      <td style="padding: 3px 0; color: #555;">Target Threshold</td>
      <td style="padding: 3px 0; text-align: right; font-weight: bold;">${target}</td>
    </tr>
    <tr style="border-bottom: 1px solid rgba(0,0,0,0.1);">
      <td style="padding: 3px 0; color: #555;">Calculation</td>
      <td style="padding: 3px 0; text-align: right; color: #666; font-size: 11px;">(3×${dex}) + (2×${lvl})</td>
    </tr>
    <tr>
      <td style="padding: 3px 0; font-weight: bold;">d100 Roll</td>
      <td style="padding: 3px 0; text-align: right; font-size: 15px; font-weight: bold;">${rollTotal}</td>
    </tr>
  </table>
</div>
`;

// Send message to Chat (Dice So Nice triggers automatically from roll)
await roll.toMessage({
  speaker: ChatMessage.getSpeaker({ actor }),
  content: messageContent,
  rollMode: game.settings.get("core", "rollMode")
});
